package ownerweb

// connectionsHTML is the «Подключения» page. All data is rendered with
// textContent; the CSP nonce is injected into the single <script> tag.
const connectionsHTML = `<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Подключения MCPshka</title>
<style>
:root{color-scheme:light dark;--bg:#f6f7f9;--card:#fff;--ink:#16181d;--mute:#5d6470;--line:#dde1e7;--ok:#137a3a;--bad:#b42318;--warn:#9a6700;--acc:#2457d6}
@media (prefers-color-scheme:dark){:root{--bg:#111318;--card:#1a1d24;--ink:#e8eaee;--mute:#9aa1ad;--line:#2c313b;--ok:#4cc27a;--bad:#ff7b6e;--warn:#e0b341;--acc:#7aa2ff}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 -apple-system,system-ui,Segoe UI,Roboto,sans-serif}
main{max-width:760px;margin:0 auto;padding:16px}h1{font-size:22px;margin:4px 0 2px}h2{font-size:15px;margin:22px 0 8px;color:var(--mute);text-transform:uppercase;letter-spacing:.04em}
.sub{color:var(--mute);margin:0 0 12px}.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px 14px;margin:0 0 10px}
.row{display:flex;gap:8px;align-items:baseline;justify-content:space-between;flex-wrap:wrap}.t{font-weight:600}.why,.hint,.meta{color:var(--mute);font-size:13px;margin-top:4px;overflow-wrap:anywhere}
.st{font-size:12px;font-weight:600;padding:2px 8px;border-radius:999px;border:1px solid currentColor;white-space:nowrap}
.connected{color:var(--ok)}.invalid,.missing{color:var(--bad)}.saved,.needs_app,.unknown{color:var(--warn)}.planned,.off{color:var(--mute)}.ask,.pin{color:var(--warn)}.add{color:var(--acc)}
form,.acts{display:flex;gap:8px;margin-top:8px;flex-wrap:wrap}input{flex:1 1 220px;min-width:0;padding:9px 10px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);font:inherit}
button{padding:9px 14px;border:0;border-radius:8px;background:var(--acc);color:#fff;font:inherit;font-weight:600}button.sec{background:transparent;color:var(--acc);border:1px solid var(--acc)}button:disabled{opacity:.5}
a{color:var(--acc)}.msg{font-size:13px;margin-top:6px;overflow-wrap:anywhere}.code{font:600 22px ui-monospace,Menlo,monospace;letter-spacing:.08em}
#status{min-height:1.4em;color:var(--mute)}button{min-height:40px;line-height:1.2}form button,.acts button{flex:0 0 auto}@media (max-width:560px){form,.acts{flex-direction:column;align-items:stretch}form input{flex:none;width:100%}form button,.acts button,form.stack button{width:100%;align-self:stretch}}form.stack{flex-direction:column;align-items:stretch}form.stack input{flex:none;width:100%}form.stack button{align-self:flex-start}details{margin-top:8px}summary{cursor:pointer}
</style></head><body><main>
<h1>Подключения</h1><p class="sub">Токены, облака и вход агентов MCPshka. Секреты только записываются: страница показывает аккаунт, права и последние 4 символа. </p><p class="sub"><a href="/connections/resources">Ресурсы</a> · <a href="/connections/containers">Контейнеры</a> · <a href="/connections/code">Код</a> · <a href="/connections/ide">IDE</a> · <a href="/connections/runners">Раннеры</a> · <a href="/connections/issues">Проблемы</a> · <a href="/connections/memory">Память</a> · <a href="/connections/plugins">Плагины</a></p>
<section id="gate" class="card"><div class="t">Вход через Face ID</div><div class="why">Сессия на 30 минут в этом браузере.</div><div class="acts"><button id="login">Войти</button></div></section>
<p id="status"></p><div id="list" hidden></div>
<div class="acts" id="tail" hidden><button class="sec" id="logout">Выйти</button></div>
</main><script>
const $=id=>document.getElementById(id);const status=$('status');
const b64bytes=x=>{const s=x.replace(/-/g,'+').replace(/_/g,'/');const a=atob(s+'='.repeat((4-s.length%4)%4));return Uint8Array.from(a,c=>c.charCodeAt(0));};
const bytesb64=x=>{const b=new Uint8Array(x);let s='';for(const v of b)s+=String.fromCharCode(v);return btoa(s).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');};
const getOptions=o=>{const p=structuredClone(o.publicKey||o);p.challenge=b64bytes(p.challenge);for(const x of (p.allowCredentials||[]))x.id=b64bytes(x.id);return {publicKey:p};};
const serialize=c=>({id:c.id,rawId:bytesb64(c.rawId),type:c.type,authenticatorAttachment:c.authenticatorAttachment,clientExtensionResults:c.getClientExtensionResults(),response:Object.fromEntries(['clientDataJSON','authenticatorData','signature','userHandle'].filter(k=>c.response[k]).map(k=>[k,bytesb64(c.response[k])]))});
async function call(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store',credentials:'same-origin'});let d={};try{d=await r.json();}catch(e){}if(!r.ok){const e=Error(d.error||('HTTP '+r.status));e.status=r.status;throw e;}return d;}
const el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;};
const LABEL={connected:'подключено',invalid:'токен отклонён',saved:'сохранён, не проверен',missing:'не подключено',unknown:'проверьте вход',planned:'скоро',pending:'ждёт подтверждения в Lane',offline:'нет связи',paused:'на паузе',off:'выключено',ask:'ждёт разрешения',add:'новый узел',pin:'ключ хоста не закреплён'};
function checkLine(c){if(!c)return '';const p=[];if(c.account)p.push('аккаунт '+c.account);if(c.scopes)p.push('права: '+c.scopes);if(c.expires)p.push('до '+c.expires);if(c.detail)p.push(c.detail);return p.join(' · ');}
function tokenForm(c,box,msg){const f=el('form');const i=el('input');i.type='password';i.autocomplete='off';i.placeholder=c.state==='missing'?'вставьте токен':'новый токен (заменит '+(c.last4||'текущий')+')';const b=el('button',null,'Проверить и сохранить');f.append(i,b);
 f.onsubmit=async e=>{e.preventDefault();if(!i.value.trim())return;b.disabled=true;msg.textContent='Проверяю у провайдера…';try{const r=await call('/connections/api/token',{id:c.id,token:i.value});i.value='';msg.textContent='Сохранён '+r.last4+'. '+checkLine(r.check);await load();}catch(x){msg.textContent=x.message;if(x.status===401)relogin();}b.disabled=false;};box.append(f);
 if(c.state!=='missing'){const a=el('div','acts');const k=el('button','sec','Проверить сейчас');k.onclick=async()=>{k.disabled=true;msg.textContent='Проверяю…';try{const r=await call('/connections/api/check',{id:c.id});msg.textContent=(r.check.ok?'Работает. ':'Не работает. ')+checkLine(r.check);await load();}catch(x){msg.textContent=x.message;}k.disabled=false;};a.append(k);box.append(a);}}
function cloudForm(c,box,msg){const a=el('div','acts');const k=el('button',null,c.state==='connected'?'Переподключить':'Подключить');a.append(k);box.append(a);
 const f=el('form');f.hidden=true;const land=el('input');land.placeholder='адрес страницы после входа (http://127.0.0.1:53682/…)';land.autocomplete='off';const b=el('button',null,'Готово');f.append(land,b);box.append(f);
 k.onclick=async()=>{k.disabled=true;if(!c.quick){try{const r=await call('/connections/api/cloud-connect',{id:c.id});location.assign(r.url);}catch(x){msg.textContent=x.message;if(x.status===401)relogin();k.disabled=false;}return;}msg.textContent='Запускаю вход…';try{const r=await call('/connections/api/cloud-start',{id:c.id});msg.replaceChildren();const l=el('a',null,'1. Открыть вход в '+c.title);l.href=r.url;l.target='_blank';l.rel='noopener';msg.append(l,el('div','meta','2. Войдите как обычно. В конце браузер покажет пустую страницу или ошибку 127.0.0.1 — это нормально.'),el('div','meta','3. Скопируйте адрес этой страницы и вставьте ниже. Вход живёт 10 минут.'));f.hidden=false;}catch(x){msg.textContent=x.message;if(x.status===401)relogin();}k.disabled=false;};
 f.onsubmit=async e=>{e.preventDefault();if(!land.value.trim())return;b.disabled=true;msg.textContent='Получаю доступ…';try{await call('/connections/api/cloud-finish',{id:c.id,landed:land.value});land.value='';f.hidden=true;msg.textContent='Подключено.';await load();}catch(x){msg.textContent=x.message;}b.disabled=false;};
 const adv=el('details');adv.append(el('summary','meta','Дополнительно: своё OAuth-приложение'));if(c.redirect_uri)adv.append(el('div','meta','Redirect URI: '+c.redirect_uri));
 const af=el('form');const id=el('input');id.placeholder='Client ID';id.autocomplete='off';const sec=el('input');sec.type='password';sec.placeholder='Client secret';sec.autocomplete='off';const sb=el('button','sec','Сохранить приложение');af.append(id,sec,sb);
 af.onsubmit=async e=>{e.preventDefault();sb.disabled=true;try{await call('/connections/api/cloud-app',{id:c.id,clientid:id.value,clientsecret:sec.value});id.value=sec.value='';msg.textContent='Приложение сохранено.';await load();}catch(x){msg.textContent=x.message;}sb.disabled=false;};adv.append(af);
 if(c.app){const ab=el('button','sec','Подключить через своё приложение');ab.onclick=async()=>{try{const r=await call('/connections/api/cloud-connect',{id:c.id});location.assign(r.url);}catch(x){msg.textContent=x.message;}};const aa=el('div','acts');aa.append(ab);adv.append(aa);}
 if(c.id!=='onedrive')box.append(adv);}
function formForm(c,box,msg){const f=el('form','stack');const inputs={};
 for(const d of (c.fields||[])){const i=el('input');i.autocomplete='off';if(d.secret){i.type='password';i.placeholder=d.label+(d.last4?' (сохранён '+d.last4+'; пусто — оставить)':'')+(d.optional?' — необязательно':'');}else{i.placeholder=d.label+(d.default?' (по умолчанию '+d.default+')':'')+(d.optional?' — необязательно':'');i.value=d.value||'';}inputs[d.key]=i;f.append(i);}
 const b=el('button',null,'Проверить и сохранить');f.append(b);box.append(f);
 f.onsubmit=async e=>{e.preventDefault();b.disabled=true;msg.textContent='Проверяю…';const fields={};for(const k in inputs)fields[k]=inputs[k].value;try{const r=await call('/connections/api/form',{id:c.id,fields});for(const k in inputs)if(inputs[k].type==='password')inputs[k].value='';msg.textContent='Сохранено. '+checkLine(r.check);await load();}catch(x){msg.textContent=x.message;if(x.status===401)relogin();}b.disabled=false;};
 if(c.state!=='missing'){const a=el('div','acts');const k=el('button','sec','Проверить сейчас');k.onclick=async()=>{k.disabled=true;try{const r=await call('/connections/api/form-check',{id:c.id});msg.textContent='Работает. '+checkLine(r.check);await load();}catch(x){msg.textContent=x.message;}k.disabled=false;};a.append(k);box.append(a);}}
function ciSecret(c,box,msg){if(c.id!=='moshub'||c.state==='missing')return;const a=el('div','acts');const k=el('button','sec','Записать в секреты CI GitVerse');k.onclick=async()=>{k.disabled=true;msg.textContent='Записываю…';try{await call('/connections/api/ci-secret',{id:c.id});msg.textContent='Секрет MOSHUB_REGISTRY_TOKEN в GitVerse обновлён.';}catch(x){msg.textContent=x.message;}k.disabled=false;};a.append(k);box.append(a);}
function agentForm(c,box,msg){const a=el('div','acts');const k=el('button',null,'Войти по коду');const s=el('button','sec','Статус');a.append(k,s);box.append(a);
 const show=r=>{msg.replaceChildren();if(r.url){const l=el('a',null,r.url);l.href=r.url;l.target='_blank';l.rel='noopener';msg.append(el('div',null,'1. Откройте: '),l,el('div',null,'2. Введите код:'),el('div','code',r.code||'…'),el('div','meta','Код живёт 15 минут. После входа нажмите «Статус».'));}else msg.textContent=r.message||r.state||'';};
 k.onclick=async()=>{k.disabled=true;msg.textContent='Запрашиваю код…';try{show(await call('/connections/api/agent-login',{id:c.id}));}catch(x){msg.textContent=x.message;}k.disabled=false;};
 s.onclick=async()=>{try{show(await call('/connections/api/agent-status',{id:c.id}));await load();}catch(x){msg.textContent=x.message;}};}
function laneForm(c,box,msg){const s=c.lane||{};const a=el('div','acts');box.append(a);
 const act=(label,path,cls,done)=>{const b=el('button',cls,label);b.onclick=async()=>{b.disabled=true;try{const r=await call('/connections/api/'+path,{id:c.id});if(done)done(r);await load();}catch(x){msg.textContent=x.message;if(x.status===401)relogin();}b.disabled=false;};a.append(b);};
 if(s.detail)msg.textContent=s.detail;
 if(s.state==='no_lane')return;
 if(s.state==='unpaired'||s.state==='error')act('Подключить через Lane','lane-pair',null,r=>{msg.replaceChildren(el('div',null,'Код в панели Lane должен совпасть:'),el('div','code',r.code||'…'));});
 if(s.state==='pending'){msg.replaceChildren(el('div',null,'Подтвердите в панели Lane код:'),el('div','code',s.code||'…'));const k=el('button','sec','Проверить');k.onclick=()=>load();a.append(k);}
 if(s.public_url){const u=s.public_url.replace(/\/+$/,'')+'/mcp';const line=el('div','meta',(s.route?s.route+' · ':'')+u);box.insertBefore(line,a);
  const cp=el('button',null,'Скопировать для ChatGPT/Claude');cp.onclick=async()=>{try{await navigator.clipboard.writeText(u);msg.textContent='Адрес скопирован.';}catch(x){msg.textContent=u;}};a.append(cp);
  act('Новый ключ','lane-rotate','sec',()=>{msg.textContent='Ключ порта обновлён.';});act('Удалить','lane-remove','sec',()=>{msg.textContent='Порт удалён из Lane.';});}}
function brainForm(c,box,msg){const a=el('div','acts');const on=c.state==='connected';
 if(c.redirect_uri)box.append(el('div','meta','Адрес возврата: '+c.redirect_uri));
 const b=el('button',on?'sec':null,on?'Выключить':(c.state==='ask'?'Разрешить':'Включить'));b.onclick=async()=>{b.disabled=true;try{await call('/connections/api/brain',{id:c.id,enabled:!on});msg.textContent=on?'Выключено: доступ отрезан.':'Включено.';await load();}catch(x){msg.textContent=x.message;if(x.status===401)relogin();}b.disabled=false;};a.append(b);box.append(a);}
function nodeAddForm(c,box,msg){const f=el('form','stack');const mk=(ph,v)=>{const i=el('input');i.placeholder=ph;i.autocomplete='off';if(v)i.value=v;f.append(i);return i;};
 const name=mk('имя (латиница, напр. vps-nl)'),host=mk('IP или имя хоста'),port=mk('порт','22'),user=mk('пользователь на узле');const b=el('button',null,'Создать ключ');f.append(b);box.append(f);
 f.onsubmit=async e=>{e.preventDefault();b.disabled=true;try{const r=await call('/connections/api/node-add',{name:name.value,host:host.value,port:parseInt(port.value||'22',10),user:user.value});msg.replaceChildren(el('div',null,'Добавьте строку в ~/.ssh/authorized_keys на узле, затем «Сверить ключ» у узла ниже:'),el('div','meta',r.node.public_key));await load();}catch(x){msg.textContent=x.message;if(x.status===401)relogin();}b.disabled=false;};}
function nodeForm(c,box,msg){const n=c.node||{};const a=el('div','acts');box.append(a);
 if(n.pinned&&n.pinned.length)box.insertBefore(el('div','meta','Закреплён ключ хоста '+n.pinned.join(', ')),a);
 if(n.public_key){const d=el('details');d.append(el('summary','meta','Ключ MCPshka для authorized_keys'),el('div','meta',n.public_key));box.insertBefore(d,a);}
 const btn=(label,cls,fn)=>{const b=el('button',cls,label);b.onclick=async()=>{b.disabled=true;try{await fn();}catch(x){msg.textContent=x.message;if(x.status===401)relogin();}b.disabled=false;};a.append(b);};
 btn('Сверить ключ',null,async()=>{msg.textContent='Спрашиваю узел…';const r=await call('/connections/api/node-scan',{name:c.id});const hk=r.host_key;msg.replaceChildren();
  const said={MATCH:'Ключ хоста совпадает с закреплённым.',NEW:'Ключ ещё не закреплён. Сверьте отпечаток с консолью провайдера:',CHANGED:'Ключ хоста СМЕНИЛСЯ. Было: '+(hk.pinned||[]).join(', ')+'. Сейчас узел показывает:'}[hk.state]||hk.state;msg.append(el('div',null,said));
  if(hk.state!=='MATCH')for(const fp of hk.fingerprints){const row=el('div','acts');const k=el('button',hk.state==='CHANGED'?'sec':null,'Принять '+fp);k.onclick=async()=>{k.disabled=true;try{await call('/connections/api/node-accept',{name:c.id,fingerprint:fp});msg.textContent='Ключ хоста закреплён.';await load();}catch(x){msg.textContent=x.message;}k.disabled=false;};row.append(k);msg.append(row);}});
 btn('Проверить связь','sec',async()=>{msg.textContent='Вхожу ключом MCPshka…';await call('/connections/api/node-check',{name:c.id});msg.textContent='Связь есть: вход по ключу, ключ хоста закреплён.';});
 btn('Проверить параметры узла','sec',async()=>{msg.textContent='Проверяю ОС, архитектуру, непривилегированный доступ и диск…';const r=await call('/connections/api/node-inspect',{name:c.id});const p=r.inspection;msg.textContent='Проверено по SSH с закреплённым ключом: '+p.os+', '+p.arch+', UID '+p.uid+', свободно '+p.available_kb+' КиБ. Это ещё не установка агента и не готовность распределённого исполнителя.';await load();});
 btn('Проверить mesh','sec',async()=>{const peer_ip=prompt('Tailscale IP узла (100.64.0.0/10 или tailnet IPv6):');if(!peer_ip)return;const peer_key=prompt('Nodekey из проверенной консоли Tailscale (nodekey:...):');if(!peer_key)return;msg.textContent='Сверяю идентичность и транспорт…';const r=await call('/connections/api/node-mesh',{name:c.id,peer_ip,peer_key});const m=r.mesh;msg.textContent='Идентичность: '+(m.identity_matched?'совпала':'не доказана')+'. Транспорт: '+(m.transport_online?'онлайн':'не подтверждён')+'. Peer ping: '+(m.peer_reachable?'доступен':'не подтверждён')+'. '+m.detail;});
 btn('Удалить узел','sec',async()=>{if(!confirm('Убрать узел '+c.title+'? Файлы ключа будут отложены в .removed.'))return;await call('/connections/api/node-remove',{name:c.id});msg.textContent='Узел убран.';await load();});}
function render(list){const root=$('list');root.replaceChildren();let group='';
 for(const c of list){if(c.group!==group){group=c.group;root.append(el('h2',null,group));}
  const box=el('section','card');const head=el('div','row');head.append(el('span','t',c.title),el('span','st '+c.state,LABEL[c.state]||c.state));box.append(head,el('div','why',c.why));
  const meta=[];if(c.last4)meta.push('токен '+c.last4);if(c.updated)meta.push('обновлён '+c.updated);const cl=checkLine(c.check);if(cl)meta.push(cl);if(meta.length)box.append(el('div','meta',meta.join(' · ')));
  if(c.hint){const h=el('div','hint',c.hint+' ');if(c.hint_url){const l=el('a',null,'Открыть');l.href=c.hint_url;l.target='_blank';l.rel='noopener';h.append(l);}box.append(h);}
  const msg=el('div','msg');
  if(c.kind==='token'){tokenForm(c,box,msg);ciSecret(c,box,msg);}else if(c.kind==='cloud')cloudForm(c,box,msg);else if(c.kind==='agent')agentForm(c,box,msg);else if(c.kind==='form')formForm(c,box,msg);else if(c.kind==='lane')laneForm(c,box,msg);else if(c.kind==='brain')brainForm(c,box,msg);else if(c.kind==='node')nodeForm(c,box,msg);else if(c.kind==='node-add')nodeAddForm(c,box,msg);
  box.append(msg);root.append(box);}}
async function load(){const d=await call('/connections/api/catalog');render(d.connections);$('gate').hidden=true;$('list').hidden=false;$('tail').hidden=false;status.textContent='';}
function relogin(){$('gate').hidden=false;$('list').hidden=true;$('tail').hidden=true;status.textContent='Сессия истекла — войдите снова.';}
$('login').onclick=async()=>{const b=$('login');b.disabled=true;status.textContent='Жду Face ID…';try{const s=await call('/connections/login',{});const c=await navigator.credentials.get(getOptions(s.options));await call('/approval/'+s.id+'/finish',{credential:serialize(c)});await call('/connections/session',{});await load();}catch(x){status.textContent=String(x.message||x);}b.disabled=false;};
$('logout').onclick=async()=>{try{await call('/connections/logout',{});}catch(e){}relogin();status.textContent='Вы вышли.';};
load().catch(e=>{if(e.status!==401)status.textContent=e.message;});
</script></body></html>`
